package bt

import (
	"encoding/binary"
	"math/bits"
	"slices"
)

// animTrack is one animation of a picture: its frames from start, the next one at cur, shown after delay more
// ticks. Each frame is its delay (a big-endian word, negative after the last) and the bytes for xorAnimationFrame.
type animTrack struct {
	start, cur []byte
	delay      int16
}

// animNode is a set of animations run together: up to five tracks (one without frames ends them).
type animNode struct {
	tracks [5]animTrack
}

// running are the animations being run, in the order they were started.
var running []*animNode

// viewAnimation is the view picture's animations.
var viewAnimation animNode

// word is the little-endian word at the start of b.
func word(b []byte) uint16 { return binary.LittleEndian.Uint16(b) }

// eachTrack runs f on the node's tracks up to the first without frames.
func (n *animNode) eachTrack(f func(t *animTrack)) {
	for i := range n.tracks {
		if n.tracks[i].start == nil {
			return
		}
		f(&n.tracks[i])
	}
}

// addAnimation starts the node's tracks and runs it after the others.
func addAnimation(n *animNode) {
	pauseAnimations()
	running = append(running, n)
	n.eachTrack(func(t *animTrack) {
		t.cur = t.start
		t.delay = int16(bits.ReverseBytes16(word(t.cur)))
		t.cur = t.cur[2:]
	})
	resumeAnimations()
}

// removeAnimation stops running the node.
func removeAnimation(n *animNode) {
	pauseAnimations()
	if i := slices.Index(running, n); i >= 0 {
		running = slices.Delete(running, i, i+1)
	}
	resumeAnimations()
}

// stepAnimationsNow counts every track's delay down and draws its next frame when it runs out; after the last
// frame the track starts over.
func stepAnimationsNow() {
	animating = 1
	for _, n := range running {
		n.eachTrack(func(t *animTrack) {
			t.delay--
			if t.delay+1 != 0 {
				return
			}
			hideCursor()
			t.cur = xorAnimationFrame(t.cur)
			t.delay = int16(word(t.cur))
			t.cur = t.cur[2:]
			if t.delay < 0 {
				t.cur = t.start
				t.delay = int16(word(t.cur))
				t.cur = t.cur[2:]
			}
			t.delay = int16(bits.ReverseBytes16(uint16(t.delay)))
		})
	}
	animating = 0
}

func pauseAnimations() {
	animationsOn = 0
	animationsWanted = 1
}

func resumeAnimations() {
	if animationsWanted != 0 {
		animationsOn = 1
	}
}

// startViewAnimation starts the view picture's animations from p: up to four, each its length (a big-endian
// word, 0 for none) and its frames.
func startViewAnimation(p []byte) {
	n := &viewAnimation
	for i := 0; i < 4; i++ {
		if w := word(p); w != 0 {
			n.tracks[i].start = p[2:]
			p = p[(bits.ReverseBytes16(w)+1)&65534+2:]
		} else {
			n.tracks[i].start = nil
		}
	}
	addAnimation(n)
}

func stopViewAnimation() {
	removeAnimation(&viewAnimation)
}

