	i:=1;
	while Pile[i].Suit<>0 do begin
		a[s]:=Pile[i];
		Pile[i].Suit:=0;
		Inc(i);
		Inc(s);
	end;

	{ Sort new hand }
	SortCards;

	{ Update Screen }
	UpDateSelection(True);
