func drawPartyLine(n int16) {
	if ((member(n).flags) & flagEmpty) != 0 {
		drawWidget(&emptyPartyLine, 0, n<<3)
	} else {
		drawWidget(partyLine(partySlot(n)), 0, n<<3)
	}
}

func computeArmorClass(n int16) int16 {
	var item int16
	var i int16
	var chp *character
	var ac int16

	chp = member(n)
	ac = 10
	if i = chp.stats[2]; i > 15 {
		ac -= i - 15
	}
	if n == 0 {
		if (chp.race) != 0 {
			ac -= int16(monsterACInfo[uint16(chp.race)]) & 31
		} else {
			return 0
		}
	} else {
		if (chp.class) == 5 {
			ac -= chp.level
		}
		i = 0
		for ; i < 8; i++ {
			if item = int16(chp.items[uint16(i)]); item != 0 && (uint16(item)&32768) != 0 {
				ac -= int16(itemACBonus[uint16(uint8(item))]) & 15
			}
		}
	}
	ac -= int16(shieldAC)
	ac -= int16(partyACBonus)
	ac -= int16(spellACBonus)
	ac += int16(partyACPenalty)
	ac -= int16(memberACBonus[uint16(n)])
	if ac > 10 {
		ac = 10
	} else if ac < -10 {
		ac = -10
	}
	chp.ac = ac
	return 0
}

func scrollTextLine() {
	hideCursor()
	scrollText()
	scrollText()
	showCursor()
}

func newLine() {
	textCol = 0
	if textRow++; textRow-1 >= 11 {
		scrollTextLine()
		textRow = 11
	}
	glyphShift = 0
}

func clearText() {
	textRow = 0
	textCol = textRow
	glyphShift = 0
	hideCursor()
	fillRect(174, 15, 305, 113, 15)
	showCursor()
}

func sortParty() {
	moveFlaggedBack(2)
	moveFlaggedBack(16)
	moveFlaggedBack(32)
	moveFlaggedBack(1)
}

func moveFlaggedBack(mask int16) {
	var i int16
	var j int16
	var k int16

	i = 1
	for ; i < 6; i++ {
		if ((member(i).flags) & mask) != 0 {
			j = i + 1
			for ; j < 7; j++ {
				if ((member(j).flags) & mask) == 0 {
					k = int16(partySlot(i))
					partyOrder[uint16(i)] = partyOrder[uint16(j)]
					partyOrder[uint16(j)] = uint8(k)
					memberACBonus[uint16(i)] = memberACBonus[uint16(j)]
					memberDamageBonus[uint16(i)] = memberDamageBonus[uint16(j)]
					memberDamageDice[uint16(i)] = memberDamageDice[uint16(j)]
					memberACBonus[uint16(j)] = 0
					memberDamageBonus[uint16(j)] = 0
					memberDamageDice[uint16(j)] = 0
					if i == int16(bardPlaying) {
						bardPlaying = uint8(j)
					} else if j == int16(bardPlaying) {
						bardPlaying = uint8(i)
					}
					break
				}
			}
			if j == 7 {
				return
			}
		}
	}
}

func resetCursorShape() {
	setCursorShape(0)
	mouseCursor = 0
}

func enableClickKeys(a int16, b int16) {
	var m uint16

	m = 65535 >> uint16(15-b)
	m &= 65535 << uint16(a)
	clickKeys |= m
}

func clearClickKeys() {
	clickKeys = 0
}

func disableClickKey(n int16) {
	clickKeys &= uint16(^(1 << uint16(n)))
}

func setClassAbbrev(c int8) {
	s := partySlot(c)
	p := partyLine(s).text
	class := classNames[uint16(chars[uint16(s)].class)]
	p[34] = charAt(class, 0)
	p[35] = charAt(class, 1)
}
